import { useEffect, useRef, useState } from "react";
import { supabase } from "../lib/supabaseClient";
import { isPhoneDevice } from "../lib/device";
import { getCurrentPosition } from "../lib/geo";
import { getDeviceToken, DEVICE_TOKEN_KEY } from "../lib/deviceBinding";
import { RESIDENCES } from "../data/residences";

// Public route: /curfew?loc=Main%20Campus%20Hostel&h=main-campus
//
// One QR poster per hostel (generated by the warden, Curfew tab). Scanning
// it with the phone's own camera opens this exact URL, so `loc` (hostel
// name) and `h` (hostel id) are already filled in. Opening /curfew directly
// (e.g. the "Scan Curfew" tile on the login page) opens this page's own
// camera scanner instead.
//
// Security: a phone can only check in/out if the student has logged in to
// DormSphere on it at least once (that login creates the device token —
// see lib/deviceBinding.js). There is no login form on this page any more:
// an unrecognised phone is sent to the normal login first. The server
// (supabase/functions/curfew-scan) also checks the phone's GPS position is
// inside the hostel being scanned.

const RETURN_TO_LOGIN_MS = 3500;

function goToLogin() {
  window.location.assign("/");
}

async function callCurfewScan(deviceToken, target, coords) {
  const { data, error } = await supabase.functions.invoke("curfew-scan", {
    body: {
      device_token: deviceToken,
      // From a poster scan these are already filled in. With neither, the
      // server finds the hostel the phone is standing in from its GPS.
      location: target.auto ? null : target.name ?? null,
      hostel_id: target.auto ? null : target.id ?? null,
      latitude: coords.latitude,
      longitude: coords.longitude,
      accuracy: coords.accuracy,
    },
  });
  // supabase-js only rejects on network failure — a 4xx/5xx from the
  // function still resolves here with `error` set from the response body.
  if (error) {
    let body = data;
    // For non-2xx responses the JSON body sits on error.context (a Response).
    if (!body && error.context?.json) {
      try {
        body = await error.context.json();
      } catch {
        /* ignore */
      }
    }
    throw new Error(body?.error || error.message || "scan_failed");
  }
  return data;
}

function CurfewScanPage() {
  const [target, setTarget] = useState(null); // { name, id }
  // "checking" | "scanner" | "locating" | "scanning" | "success" | "error" | "needs_login"
  const [phase, setPhase] = useState("checking");
  const [result, setResult] = useState(null);
  const [errorMessage, setErrorMessage] = useState("");
  const ranOnce = useRef(false);

  const runScan = async (hostel) => {
    const token = getDeviceToken();
    if (!token) {
      setPhase("needs_login");
      return;
    }

    // Location first: a check-in/out only counts when the phone is at the
    // hostel, so the GPS read happens before anything is logged.
    setPhase("locating");
    let coords;
    try {
      coords = await getCurrentPosition();
    } catch (err) {
      setErrorMessage(err.message);
      setPhase("error");
      return;
    }

    setPhase("scanning");
    try {
      const data = await callCurfewScan(token, hostel, coords);
      setResult(data);
      setPhase("success");
    } catch (err) {
      if (err.message === "device_not_recognized") {
        // Token no longer valid (revoked / account changed): login again.
        try {
          window.localStorage.removeItem(DEVICE_TOKEN_KEY);
        } catch {
          /* ignore */
        }
        setPhase("needs_login");
      } else if (err.message === "outside_hostel_area") {
        setErrorMessage(`You're not at ${hostel.name ?? "that hostel"}. Move to the entrance of that hostel and scan again.`);
        setPhase("error");
      } else if (err.message === "no_hostel_nearby") {
        setErrorMessage("You don't seem to be at any hostel entrance. Go to the entrance and try again, or scan its QR poster.");
        setPhase("error");
      } else if (err.message === "unknown_hostel") {
        setErrorMessage("This QR code isn't linked to a hostel. Ask the warden for a new poster.");
        setPhase("error");
      } else {
        setErrorMessage(err.message);
        setPhase("error");
      }
    }
  };

  // After a successful scan, send the phone back to the login page.
  useEffect(() => {
    if (phase !== "success") return undefined;
    const t = setTimeout(goToLogin, RETURN_TO_LOGIN_MS);
    return () => clearTimeout(t);
  }, [phase]);

  const proceedWith = (hostel) => {
    setTarget(hostel);
    // Keeps the URL consistent with a real poster scan, so a refresh on
    // this same phone re-checks at the same hostel instead of re-opening
    // the camera. (Auto-detected scans have no hostel to remember.)
    if (!hostel.auto && hostel.name) {
      const q = new URLSearchParams({ loc: hostel.name });
      if (hostel.id) q.set("h", hostel.id);
      window.history.replaceState(null, "", `/curfew?${q.toString()}`);
    }
    runScan(hostel);
  };

  useEffect(() => {
    if (ranOnce.current) return;
    ranOnce.current = true;
    const params = new URLSearchParams(window.location.search);
    const loc = params.get("loc");
    const id = params.get("h");
    if (loc || id) {
      const known = RESIDENCES.find((r) => r.id === id);
      proceedWith({ name: loc || known?.name || id, id: id || null });
    } else if (!getDeviceToken()) {
      // Nothing to scan with yet — no point opening the camera.
      setPhase("needs_login");
    } else {
      setPhase("scanner");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Scanning is phone-only (camera + GPS at the entrance).
  if (!isPhoneDevice()) {
    return (
      <Shell title="Phone only">
        <p className="tab__subtitle-text">
          Curfew scanning is only available on a phone. Open DormSphere on your phone at the hostel
          entrance.
        </p>
        <button type="button" className="primary-btn primary-btn--wide" onClick={goToLogin}>
          Back to login
        </button>
      </Shell>
    );
  }

  if (phase === "scanner") {
    return <QrCameraScanner onDecoded={proceedWith} />;
  }

  return (
    <Shell title="Curfew Check-In" subtitle={result?.hostel_name || (target?.auto ? "Detecting your hostel…" : target?.name)}>
      {phase === "checking" && <p className="tab__message">Checking this device…</p>}
      {phase === "locating" && <p className="tab__message">Checking your location…</p>}
      {phase === "scanning" && <p className="tab__message">Logging your scan…</p>}

      {phase === "needs_login" && (
        <>
          <p className="message message--info" role="status">
            Log in to DormSphere on this phone first. After one login you can check in and out at any
            hostel entrance just by scanning its QR code.
          </p>
          <button type="button" className="primary-btn primary-btn--wide" onClick={goToLogin}>
            Go to login
          </button>
        </>
      )}

      {phase === "success" && result && (
        <div className="glass-panel curfew-status" style={{ textAlign: "center" }}>
          <p className="curfew-status__value">
            <span className={"badge badge--" + (result.scan_type === "check_out" ? "warn" : "ok")}>
              {result.scan_type === "check_out" ? "Checked Out" : "Checked In"}
            </span>
          </p>
          {result.student_name && <p className="list-row__meta">{result.student_name}</p>}
          {result.hostel_name && <p className="list-row__meta">{result.hostel_name}</p>}
          <p className="list-row__meta">
            {new Date(result.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
          </p>
          <p className="list-row__meta">Returning to login…</p>
        </div>
      )}

      {phase === "error" && (
        <>
          <p className="message message--error" role="alert">
            {errorMessage || "Something went wrong."}
          </p>
          <button
            type="button"
            className="primary-btn primary-btn--wide"
            onClick={() => (target ? runScan(target) : goToLogin())}
          >
            Try again
          </button>
        </>
      )}

      {(phase === "success" || phase === "error") && (
        <button type="button" className="portal-switch" onClick={goToLogin}>
          Back to login
        </button>
      )}
    </Shell>
  );
}

function Shell({ title, subtitle, children }) {
  return (
    <div className="page">
      <div className="scrim" />
      <div className="container">
        <div className="card">
          <img src="/logo.png" alt="" className="avatar" aria-hidden="true" />
          <p className="brand-name">DormSphere</p>
          <h1 className="title">{title}</h1>
          {subtitle && <p className="subtitle">{subtitle}</p>}
          {children}
        </div>
      </div>
    </div>
  );
}

// Opens the phone's own camera straight away (html5-qrcode) to read a
// hostel's poster QR. If the camera can't be used, the student's hostel
// is detected from their GPS position instead (done on the server,
// which only accepts a phone standing inside a hostel's circle).
function QrCameraScanner({ onDecoded }) {
  const containerId = "curfew-qr-reader";
  const scannerRef = useRef(null);
  const [scanError, setScanError] = useState("");

  useEffect(() => {
    let cancelled = false;

    import("html5-qrcode").then(({ Html5Qrcode }) => {
      if (cancelled) return;
      const scanner = new Html5Qrcode(containerId);
      scannerRef.current = scanner;

      scanner
        .start(
          { facingMode: "environment" },
          { fps: 10, qrbox: 240 },
          (decodedText) => {
            let name = decodedText;
            let id = null;
            try {
              const u = new URL(decodedText);
              name = u.searchParams.get("loc") || name;
              id = u.searchParams.get("h");
            } catch {
              /* not a URL — treat the raw text as the hostel name */
            }
            scanner.stop().catch(() => {});
            onDecoded({ name, id });
          },
          () => {
            /* per-frame "no QR found yet" — expected, ignore */
          }
        )
        .catch((err) =>
          setScanError(
            "Couldn't open the camera. Allow camera access (and use https://), or detect your hostel from your location below. (" +
              err +
              ")"
          )
        );
    });

    return () => {
      cancelled = true;
      scannerRef.current?.stop().catch(() => {});
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Shell title="Scan Hostel QR">
      <p className="tab__subtitle-text">Point your camera at the QR poster at your hostel entrance.</p>

      {scanError && (
        <p className="message message--error" role="alert">
          {scanError}
        </p>
      )}
      <div id={containerId} style={{ width: "100%", borderRadius: "16px", overflow: "hidden" }} />

      <p className="tab__subtitle-text" style={{ marginTop: "1rem" }}>
        The hostel is picked for you from the QR poster — there is nothing to select.
      </p>
      <button
        type="button"
        className="btn-outline btn-outline--neutral"
        style={{ width: "100%" }}
        onClick={() => onDecoded({ name: null, id: null, auto: true })}
      >
        Camera not working? Detect my hostel from my location
      </button>
      <button type="button" className="portal-switch" onClick={goToLogin}>
        Back to login
      </button>
    </Shell>
  );
}

export default CurfewScanPage;
